{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    """Return (actions, goal_bucket, other_bucket_liters) using a breadth-first search."""
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two) or goal < 0:
        raise ValueError("Goal is impossible to reach with these buckets")

    caps = (bucket_one, bucket_two)

    def forbidden(state):
        if start_bucket == "one":
            return state[0] == 0 and state[1] == caps[1]
        return state[1] == 0 and state[0] == caps[0]

    start = (bucket_one, 0) if start_bucket == "one" else (0, bucket_two)
    seen = {start}
    queue = deque([(start, 1)])

    while queue:
        (a, b), moves = queue.popleft()
        if a == goal:
            return moves, "one", b
        if b == goal:
            return moves, "two", a

        pour_ab = min(a, caps[1] - b)
        pour_ba = min(b, caps[0] - a)
        for nxt in (
            (caps[0], b),
            (a, caps[1]),
            (0, b),
            (a, 0),
            (a - pour_ab, b + pour_ab),
            (a + pour_ba, b - pour_ba),
        ):
            if nxt not in seen and not forbidden(nxt):
                seen.add(nxt)
                queue.append((nxt, moves + 1))

    raise ValueError("Goal is impossible to reach with these buckets")
